window.RSDW_DATA.byId = Object.create(null);
window.RSDW_DATA.byName = Object.create(null);
for (const it of window.RSDW_DATA.items) {
  window.RSDW_DATA.byId[it.id] = it;
  window.RSDW_DATA.byName[it.name.toLowerCase()] = it;
}
window.RSDW_DATA.resolveItem = function (q) {
  if (!q) return null;
  if (this.byId[q]) return this.byId[q];
  const l = String(q).toLowerCase();
  if (this.byName[l]) return this.byName[l];
  return this.items.find((i) => i.name.toLowerCase().includes(l)) || null;
};
window.RSDW_DATA.skillName = function (id) {
  const hit = this.skills.find((s) => s.id === id);
  return hit ? hit.name : ("Skill " + String(id).slice(0, 8));
};
window.RSDW_DATA.levelFromXp = function (xp) {
  const t = this.xpTable;
  xp = Math.max(0, Number(xp) || 0);
  let lvl = 1;
  for (let i = 1; i < t.length; i++) { if (t[i] <= xp) lvl = i; else break; }
  return lvl;
};
window.RSDW_DATA.xpForLevel = function (level) {
  level = Math.max(1, Math.min(99, Number(level) || 1));
  return this.xpTable[level] || 0;
};